# TTL Boundary Tests (Fixed Policy)
# -----------------------------------------------------------------------------
class TestTTLBoundaries:
    """Tests for exact TTL expiry boundaries with fixed policy."""

    def test_ttl_expiry_exact_boundary(self, controlled_clock) -> None:
        """Item must be alive at t-epsilon and dead at t+epsilon."""
        store = MemoryStore()
        store.set("key", b"value", ttl_seconds=10.0)
        controlled_clock.advance(9.999)
        assert store.get("key") == b"value"  # Not yet expired
        controlled_clock.advance(0.001)
        assert store.get("key") is None  # Exactly at boundary

    def test_ttl_zero_means_no_expiry(self, controlled_clock) -> None:
        """TTL=0 must disable expiry entirely."""
        store = MemoryStore()
        store.set("key", b"value", ttl_seconds=0)
        controlled_clock.advance(10_000.0)
        assert store.get("key") == b"value"

    def test_ttl_negative_rejected(self) -> None:
        """Negative TTL must raise ValueError."""
        store = MemoryStore()
        with pytest.raises(ValueError):
            store.set("key", b"value", ttl_seconds=-1)

    def test_ttl_refresh_on_access(self, controlled_clock) -> None:
        """Sliding TTL: access resets expiry."""
        store = MemoryStore(ttl_policy="sliding")
        store.set("key", b"value", ttl_seconds=10.0)
        controlled_clock.advance(9.0)
        store.get("key")  # Access refreshes
        controlled_clock.advance(9.0)
        assert store.get("key") == b"value"  # Still alive due to refresh

    def test_ttl_fixed_no_refresh(self, controlled_clock) -> None:
        """Fixed TTL: access does not reset expiry."""
        store = MemoryStore(ttl_policy="fixed")
        store.set("key", b"value", ttl_seconds=10.0)
        controlled_clock.advance(9.0)
        store.get("key")  # Access does not refresh
        controlled_clock.advance(0.9)
        assert store.get("key") == b"value"  # Still alive (9.9 < 10)
        controlled_clock.advance(0.1)
        assert store.get("key") is None  # Expired at 10.0

    def test_ttl_expiry_removes_from_iteration(self, controlled_clock) -> None:
        """Expired items must not appear in iteration or keys() listing."""
        store = MemoryStore()
        store.set("a", b"1", ttl_seconds=5.0)
        store.set("b", b"2", ttl_seconds=5.0)
        controlled_clock.advance(5.0)
        assert list(store.keys()) == []  # Both expired

    def test_ttl_expiry_removes_from_len(self, controlled_clock) -> None:
        """Expired items must decrement len()."""
        store = MemoryStore()
        store.set("a", b"1", ttl_seconds=5.0)
        store.set("b", b"2", ttl_seconds=5.0)
        controlled_clock.advance(5.0)
        assert len(store) == 0

    def test_ttl_mixed_expiry(self, controlled_clock) -> None:
        """Only expired items are removed; live ones remain."""
        store = MemoryStore()
        store.set("expired", b"1", ttl_seconds=1.0)
        store.set("live", b"2", ttl_seconds=100.0)
        controlled_clock.advance(1.0)
        assert store.get("expired") is None
        assert store.get("live") == b"2"
        assert len(store) == 1


