# Capacity Eviction Tests
# -----------------------------------------------------------------------------
class TestCapacityEviction:
    """Tests for capacity limits and eviction policies."""

    def test_capacity_exceeded_raises(self) -> None:
        """When no eviction policy is set, exceeding capacity raises."""
        store = MemoryStore(max_capacity=2, eviction_policy=None)
        store.set("a", b"1")
        store.set("b", b"2")
        with pytest.raises(CapacityExceededError):
            store.set("c", b"3")

    def test_capacity_fifo_eviction(self) -> None:
        """FIFO policy evicts the oldest inserted item."""
        store = MemoryStore(max_capacity=2, eviction_policy="fifo")
        store.set("a", b"1")
        store.set("b", b"2")
        store.set("c", b"3")  # Evicts 'a'
        assert store.get("a") is None
        assert store.get("b") == b"2"
        assert store.get("c") == b"3"

    def test_capacity_lru_eviction(self) -> None:
        """LRU policy evicts the least recently accessed item."""
        store = MemoryStore(max_capacity=2, eviction_policy="lru")
        store.set("a", b"1")
        store.set("b", b"2")
        store.get("a")  # 'a' is now most recently used
        store.set("c", b"3")  # Evicts 'b' (least recently used)
        assert store.get("a") == b"1"
        assert store.get("b") is None
        assert store.get("c") == b"3"

    def test_capacity_lfu_eviction(self) -> None:
        """LFU policy evicts the least frequently accessed item."""
        store = MemoryStore(max_capacity=2, eviction_policy="lfu")
        store.set("a", b"1")
        store.set("b", b"2")
        store.get("a")
        store.get("a")  # 'a' accessed twice
        store.set("c", b"3")  # Evicts 'b' (frequency=0)
        assert store.get("a") == b"1"
        assert store.get("b") is None
        assert store.get("c") == b"3"

    def test_capacity_zero_rejected(self) -> None:
        """Zero or negative capacity must raise ValueError."""
        with pytest.raises(ValueError):
            MemoryStore(max_capacity=0)
        with pytest.raises(ValueError):
            MemoryStore(max_capacity=-1)

    def test_capacity_eviction_preserves_ttl(self, controlled_clock) -> None:
        """Evicted items must respect TTL if still alive."""
        store = MemoryStore(max_capacity=2, eviction_policy="fifo")
        store.set("a", b"1", ttl_seconds=100.0)
        store.set("b", b"2", ttl_seconds=100.0)
        store.set("c", b"3", ttl_seconds=100.0)  # Evicts 'a'
        controlled_clock.advance(50.0)
        assert store.get("a") is None  # Evicted
        assert store.get("b") == b"2"  # Still alive
        assert store.get("c") == b"3"  # Still alive


