class TestRobustness:
    """Tests for error handling and edge cases."""

    def test_set_none_key_rejected(self) -> None:
        """None key must raise TypeError."""
        store = MemoryStore()
        with pytest.raises(TypeError):
            store.set(None, b"value")

    def test_set_none_value_rejected(self) -> None:
        """None value must raise TypeError."""
        store = MemoryStore()
        with pytest.raises(TypeError):
            store.set("key", None)

    def test_get_missing_key_returns_none(self) -> None:
        """Getting a non-existent key returns None."""
        store = MemoryStore()
        assert store.get("missing") is None

    def test_delete_existing_key(self) -> None:
        """Deleting an existing key removes it."""
        store = MemoryStore()
        store.set("key", b"value")
        assert store.delete("key") is True
        assert store.get("key") is None

    def test_delete_missing_key_returns_false(self) -> None:
        """Deleting a non-existent key returns False."""
        store = MemoryStore()
        assert store.delete("missing") is False

    def test_clear_removes_all(self) -> None:
        """Clear removes all items."""
        store = MemoryStore()
        store.set("a", b"1")
        store.set("b", b"2")
        store.clear()
        assert len(store) == 0

    def test_contains_checks_live_items(self, controlled_clock) -> None:
        """Contains must return False for expired items."""
        store = MemoryStore()
        store.set("key", b"value", ttl_seconds=5.0)
        assert "key" in store
        controlled_clock.advance(5.0)
        assert "key" not in store

    def test_update_existing_key(self) -> None:
        """Updating an existing key overwrites value."""
        store = MemoryStore()
        store.set("key", b"old")
        store.set("key", b"new")
        assert store.get("key") == b"new"

    def test_update_refreshes_ttl(self, controlled_clock) -> None:
        """Updating a key resets its TTL."""
        store = MemoryStore()
        store.set("key", b"old", ttl_seconds=10.0)
        controlled_clock.advance(9.0)
        store.set("key", b"new", ttl_seconds=10.0)  # Reset TTL
        controlled_clock.advance(9.0)
        assert store.get("key") == b"new"  # Still alive


