class TestConcurrencyAndPerformance:
    """Tests for thread safety and performance bounds."""

    def test_concurrent_set_get(self) -> None:
        """Concurrent sets and gets must not corrupt state."""
        store = MemoryStore()
        errors = []

        def worker(worker_id: int):
            try:
                for i in range(100):
                    key = f"worker_{worker_id}_key_{i}"
                    store.set(key, f"value_{i}".encode())
                    assert store.get(key) == f"value_{i}".encode()
            except Exception as e:  # pragma: no cover
                errors.append(e)

        threads = [threading.Thread(target=worker, args=(i,)) for i in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert errors == []
        assert len(store) == 1000  # All items present

    def test_concurrent_eviction(self) -> None:
        """Concurrent eviction must not exceed capacity."""
        store = MemoryStore(max_capacity=100, eviction_policy="lru")
        errors = []

        def worker(worker_id: int):
            try:
                for i in range(100):
                    store.set(f"key_{worker_id}_{i}", b"value")
            except Exception as e:  # pragma: no cover
                errors.append(e)

        threads = [threading.Thread(target=worker, args=(i,)) for i in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert errors == []
        assert len(store) <= 100  # Capacity never exceeded

    def test_performance_high_churn(self) -> None:
        """High churn (set/delete cycles) must complete within time bound."""
        store = MemoryStore()
        start = time.perf_counter()
        for i in range(10_000):
            store.set(f"key_{i}", b"value")
            if i % 2 == 0:
                store.delete(f"key_{i}")
        elapsed = time.perf_counter() - start
        assert elapsed < 2.0  # 2 seconds for 10k ops

    def test_performance_ttl_scan(self, controlled_clock) -> None:
        """Expired item cleanup must be efficient."""
        store = MemoryStore()
        for i in range(1_000):
            store.set(f"key_{i}", b"value", ttl_seconds=1.0)
        controlled_clock.advance(1.0)
        start = time.perf_counter()
        store.get("key_0")  # Triggers cleanup
        elapsed = time.perf_counter() - start
        assert elapsed < 0.1  # Cleanup under 100ms
        assert len(store) == 0  # All expired


